import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { answerCache, cachedClient, memoryCache } from '../../shared/http/cache'
import type { HttpClient, HttpRequest } from '../../shared/http/client'

/** A client that answers `{ n }`, n counting its calls, or what `answer` says; and the calls it was asked. */
const counting = (answer?: (n: number, request: HttpRequest) => unknown) => {
  const calls: Array<{ path: string, request: HttpRequest }> = []
  const call: HttpClient = async (path, request) => {
    calls.push({ path, request })
    return answer ? answer(calls.length, request) : { n: calls.length }
  }
  return { call, calls }
}

beforeEach(() => {
  vi.useFakeTimers({ toFake: ['Date'], now: new Date('2026-05-01T10:00:00Z') })
})
afterEach(() => {
  vi.useRealTimers()
})

describe('memoryCache', () => {
  it('answers what it keeps until it expires, a copy each time (a caller that changes it changes no one else\'s)', () => {
    const cache = memoryCache()
    cache.set('a', { list: [1] }, 1000)
    const first = cache.get('a') as { list: number[] }
    first.list.push(2)
    expect(cache.get('a')).toEqual({ list: [1] })
    vi.advanceTimersByTime(999)
    expect(cache.get('a')).toEqual({ list: [1] })
    vi.advanceTimersByTime(1)
    expect(cache.get('a')).toBeUndefined()
  })

  it('keeps maxEntries at most, dropping the oldest; clear forgets all', () => {
    const cache = memoryCache(2)
    for (const key of ['a', 'b', 'c']) cache.set(key, key, 1000)
    expect(['a', 'b', 'c'].map(key => cache.get(key))).toEqual([undefined, 'b', 'c'])
    cache.clear()
    expect(cache.get('c')).toBeUndefined()
  })

  it('keeps maxBytes at most (as JSON), dropping the oldest; an answer bigger than a tenth of it is not kept', () => {
    const cache = memoryCache(500, 100)
    // Each is 10 as JSON (its quotes too): the eleventh makes 110.
    const keys = Array.from({ length: 11 }, (_, n) => `k${n}`)
    for (const key of keys) cache.set(key, 'x'.repeat(8), 1000)
    expect(keys.filter(key => cache.get(key) === undefined)).toEqual(['k0'])
    cache.set('big', 'x'.repeat(9), 1000)
    expect(cache.get('big')).toBeUndefined()
    expect(cache.get('k10')).toBeDefined()
  })

  it('drops what has expired when it keeps something new, so expired answers make no room scarce', () => {
    const cache = memoryCache(2)
    cache.set('long', 2, 60_000)
    cache.set('old', 1, 1000)
    vi.advanceTimersByTime(1000)
    cache.set('new', 3, 1000)
    expect(['old', 'long', 'new'].map(key => cache.get(key))).toEqual([undefined, 2, 3])
  })
})

describe('answerCache', () => {
  it('is the same cache for every caller of one source, its own for each source', () => {
    expect(answerCache('quotes')).toBe(answerCache('quotes'))
    expect(answerCache('quotes')).not.toBe(answerCache('weather'))
  })
})

describe('cachedClient', () => {
  it('answers a GET it answered within the TTL from the cache, then calls again', async () => {
    const { call, calls } = counting()
    const client = cachedClient(call, memoryCache(), 60_000)
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 1 })
    vi.advanceTimersByTime(59_999)
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 1 })
    vi.advanceTimersByTime(1)
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 2 })
    expect(calls).toHaveLength(2)
  })

  it('keeps reads apart by path, query and the call\'s own headers; the order of their keys, or a header\'s case, is the same read', async () => {
    const { call, calls } = counting()
    const client = cachedClient(call, memoryCache(), 60_000)
    await client('/things', { method: 'GET', query: { a: 1, b: 'x' }, headers: { 'X-Tenant': 't1' } })
    await client('/things', { method: 'GET', query: { b: 'x', a: 1, skip: undefined }, headers: { 'x-tenant': 't1' } })
    expect(calls).toHaveLength(1)
    await client('/things', { method: 'GET', query: { a: 2, b: 'x' }, headers: { 'X-Tenant': 't1' } })
    await client('/things', { method: 'GET', query: { a: 1, b: 'x' }, headers: { 'X-Tenant': 't2' } })
    await client('/other', { method: 'GET', query: { a: 1, b: 'x' }, headers: { 'X-Tenant': 't1' } })
    expect(calls).toHaveLength(4)
  })

  it('never keeps a failure, nor an empty answer', async () => {
    let failing = true
    const { call, calls } = counting((n) => {
      if (failing) throw new Error('down')
      return n === 2 ? undefined : { n }
    })
    const client = cachedClient(call, memoryCache(), 60_000)
    await expect(client('/things', { method: 'GET' })).rejects.toThrow('down')
    failing = false
    expect(await client('/things', { method: 'GET' })).toBeUndefined()
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 3 })
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 3 })
    expect(calls).toHaveLength(3)
  })

  it('a write is never answered from the cache, and forgets what was read once it is done, passed or failed', async () => {
    let writeFails = false
    const { call, calls } = counting((n, request) => {
      if (request.method !== 'GET' && writeFails) throw new Error('refused')
      return { n }
    })
    const cache = memoryCache()
    const client = cachedClient(call, cache, 60_000)
    await client('/things', { method: 'GET' })
    expect(await client('/things', { method: 'POST', body: {} })).toEqual({ n: 2 })
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 3 })
    writeFails = true
    await expect(client('/things/1', { method: 'DELETE' })).rejects.toThrow('refused')
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 5 })
    expect(calls.map(entry => entry.request.method)).toEqual(['GET', 'POST', 'GET', 'DELETE', 'GET'])
  })

  it('a read that was answered while a write went on is not kept: it may be what the write changed', async () => {
    let finish: (value: unknown) => void = () => {}
    let n = 0
    const call: HttpClient = async (_path, request) => {
      n++
      if (request.method === 'GET' && n === 1) return new Promise((resolve) => {
        finish = resolve
      })
      return { n }
    }
    const cache = memoryCache()
    const client = cachedClient(call, cache, 60_000)
    const slow = client('/things', { method: 'GET' })
    await client('/things', { method: 'PUT', body: {} })
    finish({ stale: true })
    expect(await slow).toEqual({ stale: true })
    expect(await client('/things', { method: 'GET' })).toEqual({ n: 3 })
  })

  it('a client made per request shares the cache it is given: one request reads what another kept', async () => {
    const { call, calls } = counting()
    const cache = memoryCache()
    await cachedClient(call, cache, 60_000)('/things', { method: 'GET' })
    expect(await cachedClient(call, cache, 60_000)('/things', { method: 'GET' })).toEqual({ n: 1 })
    await cachedClient(call, cache, 60_000)('/things', { method: 'DELETE' })
    expect(await cachedClient(call, cache, 60_000)('/things', { method: 'GET' })).toEqual({ n: 3 })
    expect(calls).toHaveLength(3)
  })
})
